insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',1,'Língua Portuguesa',null,'“A segurança pública, de forma conceitual, é uma atividade que deve ser prestada pelos órgãos estatais e pela comunidade como um todo que visa proteger a cidadania, de forma a prevenir e controlar atos de criminalidade.” Nesse primeiro período do texto, aparecem as seguintes informações sobre a segurança pública:','{"A": "o conceito de segurança pública e a história da sua criação.", "B": "as causas e as consequência da criação da segurança pública.", "C": "a definição do que seja a segurança pública e sua finalidade.", "D": "a razão da existência da segurança pública e sua história."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',2,'Língua Portuguesa',null,'“A segurança pública, de forma conceitual, é uma atividade que deve ser prestada pelos órgãos estatais e pela comunidade como um todo que visa proteger a cidadania, de forma a prevenir e controlar atos de criminalidade.” Também aprendemos, pela leitura desse segmento inicial do texto, que','{"A": "a única responsável pela segurança é a força policial.", "B": "a comunidade também deve participar da segurança.", "C": "o controle total de atos de criminalidade é impossível.", "D": "a prevenção trata das consequências dos atos criminosos."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',3,'Língua Portuguesa',null,'Segundo o texto, quando o serviço de segurança deixa de ser realizado de forma satisfatória','{"A": "torna-se necessária a mudança das regras de atuação.", "B": "a população passa a sofrer consequências graves.", "C": "a comunidade perde o direito à cidadania.", "D": "o povo perde a confiança no serviço de segurança."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',4,'Língua Portuguesa',null,'“Dada a importância constitucional desse serviço é que se conclui que o mesmo não pode ser executado de qualquer forma”. A maneira de reescrever esse segmento do texto que está adequada, mantendo-se as informações originais, é:','{"A": "A importância constitucional desse serviço conclui que o mesmo não pode ser executado de qualquer forma.", "B": "Conclui-se que o mesmo não pode ser executado de qualquer forma, dada a sua importância constitucional.", "C": "Não pode esse serviço ser executado de qualquer forma, pois esse serviço tem importância constitucional.", "D": "Dada a importância constitucional desse serviço, conclui-se que ele não pode ser executado de qualquer forma."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',5,'Língua Portuguesa',null,'“Dada a importância constitucional desse serviço é que se conclui que o mesmo não pode ser executado de qualquer forma e sim de modo satisfatório, pois, quando não o é, a sociedade fica sujeita a diversos tipos de violência”; nesse segmento do texto, o pronome “o” sublinhado substitui um termo anterior, que é:','{"A": "o mesmo.", "B": "executado de qualquer forma.", "C": "executado de modo satisfatório.", "D": "importância constitucional."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',6,'Língua Portuguesa',null,'Algumas palavras presentes no texto foram selecionadas abaixo. Assinale a opção que mostra um sinônimo adequado para a palavra selecionada.','{"A": "atividade / profissão.", "B": "comunidade / vizinhança.", "C": "sociedade / população.", "D": "agressividade / marginalidade."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',7,'Língua Portuguesa',null,'Assinale a frase opinativa sobre o texto que está construída com sentido figurado.','{"A": "O texto é claro como água.", "B": "O texto mostra opiniões seguras.", "C": "O texto é curto, mas preciso.", "D": "O texto traz informações de valor."}'::jsonb,'A',true,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',8,'Língua Portuguesa',null,'Todas as frases abaixo iniciam um texto; assinale aquela que mostra marcas de um texto literário.','{"A": "Diariamente o batalhão policial inicia seu trabalho cedo.", "B": "Todos os dias ele acordava e preparava-se para trabalhar.", "C": "Os quartéis militares têm atividade constante.", "D": "Os serviços de segurança são indispensáveis."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',9,'Língua Portuguesa',null,'Em todas as frases abaixo está presente a palavra segurança; assinale aquela frase em que o significado da palavra é diferente do de todas as demais frases.','{"A": "O serviço de segurança do shopping é muito eficiente.", "B": "Os guardas respondem às perguntas com segurança.", "C": "Há muitos dispositivos eletrônicos na segurança das casas.", "D": "A polícia se encarrega da segurança do bairro."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',10,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','O texto é um resumo de um trabalho escrito sobre a segurança pública no Brasil. Nesse resumo há críticas a vários aspectos dos serviços de segurança. Assinale a opção que mostra uma crítica que não está referida no texto.','{"A": "A impunidade presente em muitos casos.", "B": "Falhas na política brasileira que prejudicam a segurança.", "C": "A violência reiterada de alguns agentes criminosos.", "D": "O trabalho mal remunerado da polícia."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',11,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','“Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública brasileira, enfatizando suas falhas.” Esse primeiro período do texto tem a finalidade principal de','{"A": "mostrar o cuidado tomado com a análise feita.", "B": "indicar que se trata de um estudo feito por cientistas.", "C": "destacar o conteúdo abordado no trabalho.", "D": "demonstrar tratar-se de uma análise imparcial dos fatos."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',12,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','“Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões.” Entre os termos sublinhados no fragmento textual acima, assinale aquele que foi substituído de forma inadequada.','{"A": "do Brasil / brasileira.", "B": "de impunidade / impune.", "C": "da polícia / policial.", "D": "das prisões / carcerário."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',13,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','“Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas.” Nesse período do texto, o pronome demonstrativo “esse” pode ser substituído por “este”, mesmo não sendo obrigatória a substituição. Assinale a frase abaixo em que o demonstrativo “esse” deve ser obrigatoriamente substituído por “este”.','{"A": "Li em “Ressurreição”, de Machado de Assis, passagens brilhantes, apesar de não ser esse o melhor romance dele.", "B": "Comprei um vinho chileno e um argentino, mas entre esse e aquele não sei qual o melhor.", "C": "Esse livro que o conferencista citou merece ser comprado.", "D": "Deixe na varanda esse guarda-chuva que você tem na mão direita."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',14,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','No texto há um erro gramatical. Assinale a opção que identifica corretamente esse erro.','{"A": "A frase iniciada pela forma de gerúndio “Sendo” deveria ser precedida de vírgula e não separada por ponto.", "B": "A preposição “sobre” na primeira linha do texto deveria ser substituída por “sob”.", "C": "A forma de gerúndio “enfatizando” deveria, por clareza, ser substituída por “com ênfase nas”.", "D": "A expressão “bem como” perderia a ambiguidade se fosse substituída por “assim como”."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',15,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','A seguinte palavra empregada no texto mostra duplicidade de formas gráficas igualmente corretas:','{"A": "análise / análize.", "B": "enfatizando / enfatisando.", "C": "aspecto / aspeto.", "D": "assola / açola."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',16,'Língua Portuguesa',null,'Assinale a frase abaixo que mostra erro de concordância verbal.','{"A": "Chegou um milhão de revólveres para a polícia.", "B": "Veio presa uma quadrilha de assaltantes de bancos.", "C": "O policial e o assaltante se enfrentou durante o assalto.", "D": "As vítimas identificaram as fotos dos criminosos."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',17,'Língua Portuguesa',null,'A regência é um dos tópicos dos conteúdos desta prova; assinale a frase abaixo que mostra regência gramaticalmente correta.','{"A": "O criminoso esqueceu da arma na cena do crime.", "B": "O prisioneiro namorou com a advogada por dois anos.", "C": "O prefeito entregou o prêmio os melhores policiais.", "D": "A prisão implica a aplicação de uma pena."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',18,'Língua Portuguesa','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.”','Assinale a opção que mostra vocábulos que são acentuados em função da mesma regra de acentuação gráfica.','{"A": "público / política.", "B": "polícia / será.", "C": "além / réus.", "D": "é / à."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',19,'Língua Portuguesa','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.”','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” Assinale a opção que apresenta corretamente o sentido de uma dessas palavras ou expressões do texto.','{"A": "Dessa forma / modo.", "B": "como / comparação.", "C": "além disso / lugar.", "D": "mais / quantidade."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',20,'Língua Portuguesa','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.”','Nas opções abaixo, há duas palavras presentes no texto; assinale a opção em que a troca de posição dessas palavras altera o seu sentido original.','{"A": "trabalho científico / científico trabalho.", "B": "sociedade mais segura / mais segura sociedade.", "C": "será evidenciada a violência / será a violência evidenciada.", "D": "diversos processos penais / processos penais diversos. Raciocínio Lógico"}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',21,'Raciocínio Lógico',null,'Em grupo de desportistas, todos os ciclistas jogam futebol e alguns ciclistas jogam basquete. Com respeito aos indivíduos desse grupo, pode-se afirmar que','{"A": "todos aqueles que jogam futebol também são ciclistas.", "B": "todos aqueles que jogam basquete também são ciclistas.", "C": "quem não joga futebol não é ciclista.", "D": "quem é ciclista joga basquete."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',22,'Raciocínio Lógico',null,'Considere a seguinte afirmação: “Se todos os cidadãos contribuem, então o país melhora” Ela apresenta a estrutura lógica 𝑝→𝑞. Tal afirmação é logicamente equivalente a','{"A": "“Se nenhum cidadão contribui, então o país piora”.", "B": "“Se o país não melhora, então nem todo cidadão contribui’.", "C": "“Se algum cidadão não contribui, então o país não melhora”.", "D": "“Se o país piora, então algum cidadão não contribui”."}'::jsonb,'B',true,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',23,'Raciocínio Lógico',null,'As figuras abaixo ilustram as 3 primeiras etapas da sucessiva transformação de um polígono em outro. Essa modificação é feita removendo-se todos os “bicos” do polígono anterior para obter- se o polígono seguinte. Etapa 1 Etapa 2 Etapa 3 A figura obtida na Etapa 4 será um polígono com','{"A": "16 lados.", "B": "20 lados.", "C": "24 lados.", "D": "36 lados."}'::jsonb,'C',true,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',24,'Raciocínio Lógico',null,'Em um conjunto de 20 objetos, 12 têm a característica A e 9 têm a característica B. Apenas 3 dos objetos não possuem nem a característica A, nem a característica B. Assim, a quantidade de objetos desse conjunto que possuem simultaneamente as características A e B é igual a','{"A": "1.", "B": "2.", "C": "3.", "D": "4."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',25,'Raciocínio Lógico',null,'Em uma caixa, há 2 bolas brancas e 3 bolas pretas. De forma totalmente aleatória, Almir sorteará uma bola por vez dessa caixa, sem que nunca sejam repostas, encerrando as extrações assim que, entre as sorteadas, houver pelo menos uma de cada cor. O número máximo de bolas que Almir pode sortear é igual a','{"A": "2.", "B": "3.", "C": "4.", "D": "5."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',26,'Raciocínio Lógico',null,'Pereira, Rodrigues, Santos e Tavares são soldados que disputam uma corrida. Em certo momento da competição, as suas posições são tais que: - se Tavares ultrapassar 2 soldados, passará a ser o 1º colocado; - Pereira não é o último colocado; - Santos não pode ultrapassar ninguém. Se apenas essas quatro pessoas estão disputando a corrida, conclui-se que','{"A": "Santos está em primeiro e Rodrigues está em terceiro.", "B": "Pereira está em primeiro e Tavares está em terceiro.", "C": "Pereira está em segundo e Rodrigues está em quarto.", "D": "Rodrigues está em segundo e Tavares está em terceiro."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',27,'Raciocínio Lógico',null,'Um soldado iniciou um treinamento para uma prova de flexão de braço fazendo, no primeiro dia, um total de 6 repetições da seguinte forma: - 1 repetição na 1ª série; - 2 repetições na 2ª série; e - 3 repetições na 3ª série. No segundo dia, o soldado fez um total de 10 repetições da seguinte forma: - 1 repetição na 1ª série; - 2 repetições na 2ª série; - 3 repetições na 3ª série; e - 4 repetições na 4ª série. E assim, a cada dia, o soldado acrescentou uma série a mais ao treino do dia anterior com uma repetição a mais, de modo que a nª série tem n repetições. Mantendo o padrão, o soldado deverá fazer, no 8º dia de treinamento, um total de','{"A": "55 repetições.", "B": "66 repetições.", "C": "78 repetições.", "D": "91 repetições."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',28,'Raciocínio Lógico',null,'São logicamente verdadeiras as seguintes afirmações: I. Eu sou casado ou eu não sou policial. II. Eu não tenho filho e eu não sou casado. A partir dessas informações, pode-se afirmar que','{"A": "eu não sou casado, sou policial e não tenho filho.", "B": "eu não sou casado, não sou policial e não tenho filho.", "C": "eu sou casado, sou policial e tenho filho.", "D": "eu sou casado, não sou policial e tenho filho."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',29,'Raciocínio Lógico',null,'Considere a seguinte afirmação: “Todas as pessoas apreendidas têm 21 anos ou mais e são do sexo masculino” A negação dessa afirmação é:','{"A": "Nenhuma pessoa apreendida tem 21 anos ou mais ou é do sexo masculino.", "B": "Nenhuma pessoa apreendida tem 21 anos ou mais e é do sexo masculino.", "C": "Pelo menos uma das pessoas apreendidas tem menos de 21 anos e é do sexo feminino.", "D": "Pelo menos uma das pessoas apreendidas tem menos de 21 anos ou é do sexo feminino."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',30,'Raciocínio Lógico',null,'Uma sequência de números inteiros foi criada escolhendo-se os dois primeiros termos e, a partir do 3º termo, os próximos números da sequência foram calculados por meio de uma mesma operação básica envolvendo os dois antecessores imediatos. A seguir, são apresentados os seis primeiros termos dessa sequência numérica. 2, -1, 1, 0, 1, 1, ... Seguindo esse padrão de construção, o valor do próximo termo é','{"A": "2.", "B": "1.", "C": "0.", "D": "-1. Conhecimentos Específicos"}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',31,'Direito Penal',null,'Suponha que, no interior de uma aeronave privada brasileira a serviço do governo brasileiro, foi cometido um delito de furto quando tal aeronave estava localizada em aeroporto de país estrangeiro. Nesse caso, de acordo com o Código Penal brasileiro, é correto afirmar que','{"A": "pelo princípio da territorialidade, deverá ser aplicada apenas a lei penal estrangeira, uma vez que se trata de aeronave privada, ainda que a serviço do governo brasileiro, que se encontrava em território estrangeiro no momento em que o delito foi cometido.", "B": "poderá ser aplicada a lei penal brasileira, por serem consideradas como extensão do território nacional as aeronaves brasileiras, ainda que privadas, a serviço do governo brasileiro, onde quer que se encontrem.", "C": "pelo princípio da extraterritorialidade da lei penal brasileira, esta poderá ser aplicada ao delito cometido no interior de aeronave privada brasileira a serviço do governo brasileiro, desde que haja requerimento do Ministro da Justiça às autoridades estrangeiras do país onde o delito foi cometido.", "D": "pelo princípio da extraterritorialidade da lei penal brasileira, esta poderá ser aplicada ao delito cometido no interior de aeronave privada brasileira a serviço do governo brasileiro, desde que haja requerimento do Ministro das Relações Exteriores às autoridades estrangeiras do país onde o delito foi cometido."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',32,'Direito Penal',null,'Sobre as excludentes de ilicitude reconhecidas pelo Direito Penal Brasileiro, é correto afirmar que','{"A": "a legítima defesa, o estado de necessidade, o estrito cumprimento de dever legal, o exercício regular de direito e o consentimento do ofendido são excludentes que, expressamente, encontram-se previstas no Código Penal.", "B": "dentre todas as excludentes de ilicitude, o excesso punível somente é previsto para a legítima defesa.", "C": "não pode alegar estado de necessidade quem tinha o dever legal de enfrentar o perigo.", "D": "configura-se a legítima defesa quando o agente, usando moderadamente dos meios necessários, repele injusta agressão, atual ou iminente, a direito próprio. Quando visa a repelir injusta agressão a terceiros, age-se em estado de necessidade."}'::jsonb,'C',true,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',33,'Direito Penal',null,'Paulo, pai de Joaquim e Ana, todas as vezes em que tem ciência de que sua filha chegou em casa após as 22h, a agride fisicamente. O mesmo não ocorre em relação ao seu filho, com quem é sempre mais compreensivo. Certo dia, Paulo extrapola nas agressões físicas e mata Ana. Cumpre destacar que Paulo não reside no mesmo local que seus filhos já que, desde pequenos, moram com a avó materna. Sobre a situação narrada, é correto afirmar que','{"A": "Paulo cometeu homicídio qualificado contra sua filha Ana, na modalidade feminicídio.", "B": "Paulo cometeu homicídio qualificado por motivo fútil, não sendo possível a tipificação da conduta por feminicídio, em razão de não ter sido cometido no âmbito da violência doméstica, já que o agente não residia com a vítima.", "C": "No caso mencionado, somente seria possível a tipificação da conduta como feminicídio caso a vítima tivesse relação afetiva com o agente, como namoro ou união estável.", "D": "Nos termos do Código Penal, para a configuração do feminicídio, basta a constatação de o agente ser homem e a vítima ser mulher."}'::jsonb,'A',true,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',34,'Legislação Especial e Direitos Humanos',null,'Acerca da Declaração Universal dos Direitos Humanos (ONU, 1948), analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O casamento não será válido senão com o livre e pleno consentimento dos nubentes, vedando-se a prática da poligamia. ( ) Ninguém poderá ser culpado por qualquer ação ou omissão que, no momento, não constituíam delito perante o direito nacional ou internacional. Também não será imposta pena mais forte do que aquela que, no momento da prática, era aplicável ao ato delituoso. ( ) Todo ser humano, vítima de perseguição, tem o direito de procurar e de gozar asilo em outros países, salvo em caso de perseguição legitimamente motivada por crimes de direito comum ou por atos contrários aos objetivos e princípios das Nações Unidas. As afirmativas são, respectivamente,','{"A": "V - V - V.", "B": "F - V - V.", "C": "V - F - F.", "D": "F - V - F."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',35,'Legislação Especial e Direitos Humanos',null,'Acerca dos crimes de preconceito de raça ou de cor, previstos na Lei nº 7.716/89, é correto afirmar que','{"A": "se o crime de induzir preconceito de raça for cometido pelos meios de comunicação social, uma medida possível de combate ao preconceito é a interdição das respectivas mensagens na rede mundial de computadores.", "B": "serão punidos, na forma da Lei nº 7.716/89, os crimes resultantes de discriminação ou preconceito de raça, cor ou etnia. Os crimes resultantes de preconceito de religião ou procedência nacional não são abarcados pela referida lei.", "C": "constitui efeito automático da condenação a perda do cargo ou função pública, para o servidor público, e a suspensão do funcionamento do estabelecimento particular por prazo não superior a três meses.", "D": "a conduta de veicular símbolos que utilizem a cruz suástica, para fins de divulgação do nazismo, não constitui crime, em razão do direito fundamental à liberdade de expressão."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',36,'Legislação Especial e Direitos Humanos',null,'Nos termos da Lei nº 9.455/97, que define os crimes de tortura, quando um agente policial submete alguém, sob sua guarda, poder ou autoridade, com emprego de violência ou grave ameaça, a intenso sofrimento físico ou mental, como forma de aplicar castigo pessoal ou medida de caráter preventivo, é possível afirmar que','{"A": "não há previsão legal de punição penal para aquele que se omite em face dessas condutas, quando tinha o dever de evitá-las ou apurá-las.", "B": "o crime de tortura é inafiançável e insuscetível de graça, cabendo, contudo, o benefício da anistia em situações excepcionais.", "C": "a condenação acarretará a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada.", "D": "sendo o crime cometido por agente policial, aumenta-se a pena de um terço até metade."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',37,'Legislação Especial e Direitos Humanos',null,'Nos termos do Estatuto da Criança e do Adolescente – Lei nº 8.069/90, é correto afirmar que','{"A": "um adolescente de 14 (quatorze) anos que pratica vias de fato contra alguém, conduta tipificada na Lei de Contravenções Penais, não comete ato infracional.", "B": "são penalmente inimputáveis os menores de dezoito anos, sujeitos às medidas previstas nesta Lei, salvo quando emancipados, a partir de dezesseis anos, passando a adquirir imputabilidade criminal.", "C": "é vedada a internação do adolescente antes do trânsito em julgado da sentença.", "D": "o adolescente civilmente identificado não será submetido à identificação compulsória pelos órgãos policiais, de proteção e judiciais, salvo para efeito de confrontação, havendo dúvida fundada."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',38,'Direito Processual Penal',null,'José foi preso por agente policial em flagrante delito, no instante em que cometia a infração penal. Nesse caso, é correto afirmar que','{"A": "caso José fosse encontrado, logo depois, com instrumentos que fizessem presumir ser ele autor da infração, ainda assim, não haveria possibilidade de sua prisão em flagrante delito.", "B": "nos termos do Código de Processo Penal, o flagrante delito somente é verificado quando o agente está cometendo a infração penal ou acabou de cometê-la.", "C": "em razão de ter sido preso em flagrante delito, não é permitido a José prestar fiança em qualquer circunstância.", "D": "caso haja falta de testemunhas da infração, tal fato não impedirá o auto de prisão em flagrante; mas, nesse caso, com o condutor, deverão assiná-lo pelo menos duas pessoas que hajam testemunhado a apresentação do preso à autoridade."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',39,'Legislação Especial e Direitos Humanos',null,'Acerca da Lei nº 13.869/19, que dispõe sobre os crimes de abuso de autoridade, é correto afirmar que','{"A": "constitui crime de abuso de autoridade constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo.", "B": "não constitui crime de abuso de autoridade decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais, pois, para tal situação, existe a possibilidade de relaxamento da prisão ilegal.", "C": "somente servidores públicos, no exercício de suas funções ou a pretexto de exercê-las, podem ser agentes dos delitos previstos na referida lei.", "D": "deixar de identificar-se ou identificar-se falsamente ao preso por ocasião de sua captura ou quando deva fazê-lo durante sua detenção ou prisão não constitui crime de abuso de autoridade, pois visa a resguardar a integridade do agente policial."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',40,'Direito Penal',null,'José foi flagrado pela autoridade policial cometendo crime de menor potencial ofensivo. Nessa hipótese, nos termos da Lei nº 9.099/95, é correto afirmar que','{"A": "ao autor do fato que, após a lavratura do termo, for imediatamente encaminhado ao Juizado ou assumir o compromisso de a ele comparecer, se imporá prisão em flagrante.", "B": "a soltura do preso em flagrante delito por crime de menor potencial ofensivo somente será possível mediante a prestação de fiança.", "C": "a autoridade policial que tomar conhecimento da ocorrência lavrará termo circunstanciado e o encaminhará imediatamente ao Juizado, com o autor do fato e a vítima, providenciando-se as requisições dos exames periciais necessários.", "D": "em caso de violência doméstica, o juiz não poderá determinar, antes do trânsito em julgado da sentença, seu afastamento do lar, domicílio ou local de convivência com a vítima."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',41,'Direito Penal Militar',null,'Acerca das disposições contidas no Código Penal Militar, julgue os itens a seguir: I. É punível com pena de detenção a conduta de embriagar-se o militar, quando em serviço, ou apresentar-se embriagado para prestá-lo. II. É punível com detenção a conduta de dormir o militar, quando em serviço, como oficial de quarto ou de ronda, ou em situação equivalente, ou, não sendo oficial, em serviço de sentinela, vigia, plantão às máquinas, ao leme, de ronda ou em qualquer serviço de natureza semelhante. III. É punível com reclusão desacatar superior, ofendendo-lhe a dignidade ou o decoro, ou procurando deprimir-lhe a autoridade. Está correto o que se afirma em','{"A": "I e II, apenas.", "B": "II e III, apenas.", "C": "I e III, apenas.", "D": "I, II e III."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',42,'Direito Constitucional',null,'Assinale a opção que representa um direito ou garantia individual previsto expressamente no Art. 5º da Constituição Federal de 1988.','{"A": "Todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo exigida autorização prévia da autoridade competente.", "B": "A casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial.", "C": "A prática do racismo constitui crime inafiançável, porém prescritível em 15 (quinze) anos, sujeito à pena de reclusão, nos termos da lei.", "D": "Não haverá pena de morte, mesmo em caso de guerra declarada."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',43,'Direito Processual Penal',null,'Acerca das disposições previstas no Código de Processo Penal Militar, é correto afirmar que','{"A": "o inquérito policial militar é a apuração sumária de fato, que, nos termos legais, configure crime militar e de sua autoria, tendo caráter de instrução definitiva.", "B": "nas infrações permanentes, considera-se o agente em flagrante delito enquanto não cessar a permanência.", "C": "é definitiva a prisão que ocorre durante o inquérito, ou no curso do processo, ainda que antes da condenação.", "D": "somente os militares poderão prender quem for insubmisso ou desertor."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',44,'Legislação de Trânsito',null,'Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência é conduta prevista no Código de Trânsito Brasileiro (CTB). Sobre o tema, é correto afirmar que','{"A": "a conduta descrita somente será crime previsto no CTB se for constatada concentração igual ou superior a 6 decigramas de álcool por litro de sangue ou igual ou superior a 0,3 miligrama de álcool por litro de ar alveolar.", "B": "a conduta descrita será crime e infração administrativa previstos no CTB qualquer que seja a concentração de álcool por litro de sangue ou por litro de ar alveolar.", "C": "em se tratando de conduta criminosa, a capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência somente poderá ser obtida mediante teste de alcoolemia ou toxicológico ou exame clínico.", "D": "a conduta descrita somente será infração administrativa prevista no CTB se for constatada concentração igual ou superior a 9 decigramas de álcool por litro de sangue ou igual ou superior a 0,6 miligrama de álcool por litro de ar alveolar."}'::jsonb,'X',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','questão ANULADA pela banca; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',45,'Legislação Especial e Direitos Humanos',null,'A violência doméstica contra a mulher, infelizmente, é uma realidade que, todos os dias, aterroriza milhares de brasileiras. Muitas mulheres não são capazes de se libertar dessa situação por medo ou dependência emocional e econômica dos parceiros. Sobre esse tema, de acordo com a Lei Maria da Penha – Lei nº 11.340/06, é correto afirmar que','{"A": "embora existam outras formas de violência doméstica contra a mulher, a Lei Maria da Penha somente menciona expressamente a violência física e sexual.", "B": "é direito da mulher em situação de violência doméstica e familiar o atendimento policial e pericial especializado, ininterrupto e prestado por servidores - preferencialmente do sexo feminino - previamente capacitados.", "C": "a inquirição de mulher em situação de violência doméstica, quando se tratar de crime contra a mulher, obedecerá, dentre outras, à diretriz de garantir o contato direto da mulher, seus familiares e testemunhas com o investigado para fins de acareação.", "D": "verificada a existência de risco atual à vida da mulher em situação de violência doméstica, o agressor somente poderá ser afastado do lar, em qualquer hipótese, por ordem judicial."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',46,'Legislação Institucional (PM-SP)',null,'Acerca da Lei Complementar nº 893/01, do Estado de São Paulo, que institui o Regulamento Disciplinar da Polícia Militar, é correto afirmar que','{"A": "transgressão disciplinar é a infração criminal caracterizada pela violação dos deveres policiais-militares, cominando ao infrator as sanções previstas no Código Penal Militar.", "B": "as transgressões disciplinares são classificadas de acordo com sua gravidade em graves (G), médias (M) e leves (L).", "C": "não constitui transgressão disciplinar dormir em serviço de policiamento, vigilância ou segurança de pessoas ou instalações, desde que haja mais de um policial no local.", "D": "as sanções disciplinares aplicáveis aos militares do Estado, independentemente do posto, graduação ou função que ocupem, são detenção, demissão e expulsão, apenas."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',47,'Legislação Institucional (PM-SP)',null,'De acordo com as I-21-PM, Instruções para continências, honras, sinais de respeito e cerimonial militar na Polícia Militar, assinale a afirmativa incorreta.','{"A": "Para falar, formalmente, ao Comandante Geral, o tratamento é \"Vossa Excelência\".", "B": "O Secretário da Segurança Pública do Estado do Paraná, quando em visita de caráter oficial ao Estado de São Paulo, tem direito à continência.", "C": "O Teto de Honra, para as praças da ativa, da reserva ou reformados, consiste em homenagens aos nubentes, a fim de dar boas-vindas à família policial-militar por conta das cerimônias de enlace matrimonial.", "D": "Na continência da guarda, o comandante da guarda comandará: “APRESENTAR-ARMA!, OLHAR À ESQUERDA!” caso a autoridade visitante seja o Comandante-Geral da PM."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',48,'Legislação Institucional (PM-SP)',null,'O uniforme é o símbolo da autoridade e seu uso correto é fator primordial na apresentação individual e coletiva do policial militar, contribuindo para o fortalecimento da disciplina e para a boa imagem da Instituição. De acordo com os Regulamentos de Uniformes da Polícia Militar - R-5-PM, é correto afirmar que','{"A": "os uniformes da Polícia Militar classificam-se em três categorias apenas: formais, operacionais básicos e específicos.", "B": "a posse do uniforme SM-1 [Social (Passeio Completo) Masculino - 1] será obrigatória para os Oficiais e facultada para as Praças.", "C": "a posse do uniforme GM-1 (Gala Masculino – 1) será obrigatória para Subcomandante da Polícia Militar (Subcmt PM) e Praças.", "D": "a posse do uniforme PM-1 (Passeio Masculino - 1) será obrigatória para os Oficiais e Praças."}'::jsonb,'B',true,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',49,'Legislação Especial e Direitos Humanos',null,'José foi flagrado por agente policial consumindo cigarro de maconha. No mesmo local, foram identificadas duas mudas plantadas de cannabis sativa com o fim de confecção de cigarros de maconha apenas para consumo próprio recreativo de José. De acordo com a Lei nº 11.343/06, que institui o Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad, é correto afirmar que','{"A": "o consumo e plantio de maconha para uso próprio e com fins recreativos não são mais considerados crimes no ordenamento jurídico brasileiro.", "B": "o consumo de maconha para uso próprio e com fins recreativos não é mais considerado crime no ordenamento jurídico brasileiro, mas seu plantio, ainda que para consumo próprio e com fins recreativos, permanece criminalizado.", "C": "o consumo e plantio de maconha para uso próprio e com fins recreativos são crimes puníveis com pena de detenção, de seis meses a um ano, e multa.", "D": "o consumo e plantio de maconha para uso próprio e com fins recreativos são crimes, embora não sejam mais puníveis com pena privativa de liberdade."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',50,'Legislação Especial e Direitos Humanos',null,'Paulo, cidadão que possui registro regular de posse de arma, foi flagrado na via pública por agente policial portando arma de fogo desmuniciada, de uso permitido e devidamente registrada em seu nome, quando se dirigia de sua casa para seu escritório. Nesse caso, sobre a possibilidade de transitar com sua arma nas ruas, é correto afirmar que','{"A": "a posse regular de arma de fogo presume a autorização para porte de trânsito em todo território nacional.", "B": "a posse regular de arma de fogo não presume a autorização para porte de arma de fogo, que deve ser concedida pela Polícia Federal.", "C": "a concessão de autorização para porte de arma de fogo é de competência da Polícia Civil do Estado em que o certificado de posse foi expedido.", "D": "a autorização para porte de trânsito de arma de fogo deverá possuir eficácia territorial e temporal ilimitada."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',51,'Legislação Institucional (PM-SP)',null,'De acordo com as Instruções para Afastamentos na Polícia Militar do Estado de São Paulo – I-36-PM, é correto afirmar que','{"A": "a licença-adoção não é reconhecida de forma expressa na I- 36-PM.", "B": "todo policial militar terá direito a usufruir 5 (cinco) dias de licença-paternidade quando ocorrer o nascimento (com vida) de seu filho. Na ocorrência do nascimento de mais de um filho na mesma data, será concedida licença de 10 (dez) dias.", "C": "todo policial militar terá direito a período de luto de 2 (dois) dias em caso de falecimento de neto.", "D": "toda policial militar terá direito a usufruir 160 (cento e sessenta) dias de licença-gestante, a qual, mediante prescrição médica, poderá ser iniciada a partir da 34ª (trigésima quarta) semana de gestação."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',52,'Legislação Institucional (PM-SP)',null,'Acerca dos conceitos presentes na Nota de Instrução PM3-1/02/15 - Sistemática de Atuação da Polícia Militar no Atendimento e Registro de Ocorrências - Resolução SSP-57/2015 -, julgue as afirmativas a seguir. I. O “atendimento preferencial” consiste em atender a unidade de serviço em serviço, quando da apresentação de ocorrência criminal em unidade da Polícia Civil (Delegacia ou Distrito Policial), com a celeridade possível, visando a seu retorno às atividades de polícia ostensivo-preventiva, respeitados os critérios de prioridade de atendimento estabelecidos na Constituição Federal e legislação infraconstitucional. II. A “comunicação” consiste em cientificar o Delegado de Polícia acerca de ocorrência criminal atendida pela Polícia Militar. III. A “Notificação de Ocorrência - NOc” consiste em formulário sumário elaborado pelas unidades de serviço, no próprio local de atendimento, com dados básicos sobre a ocorrência e a qualificação dos policiais militares responsáveis pelo atendimento e das partes envolvidas. Está correto o que se afirma em','{"A": "I e II, apenas.", "B": "I e III, apenas.", "C": "II e III, apenas.", "D": "I, II e III."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',53,'Legislação Institucional (PM-SP)',null,'De acordo com a Portaria do Cmt G CORREGPM-1/360/13, que regulamenta o procedimento disciplinar, é correto afirmar que','{"A": "vislumbrado o cometimento de transgressão disciplinar, a autoridade competente, instaurará o Procedimento Disciplinar, com a sua autuação e a elaboração do Termo Acusatório, motivado com as razões de fato e de direito, para que o acusado possa exercitar o seu direito à ampla defesa e ao contraditório.", "B": "ao receber a comunicação disciplinar, a autoridade competente analisará os fatos, no prazo de 5 (cinco) dias e, caso vislumbre que ela não preenche os requisitos suficientes para a formulação de Termo Acusatório, poderá apenas arquivá-la.", "C": "para se evitar constrangimentos entre as partes, não será admitida acareação entre acusados, entre acusado e testemunha, entre testemunhas, entre acusado ou testemunha e a pessoa ofendida, e entre as pessoas ofendidas, mesmo se divergirem, em suas declarações, sobre fatos ou circunstâncias relevantes.", "D": "a falta de defesa técnica por advogado ofende os direitos constitucionais de ampla defesa e contraditório do acusado, importando a remarcação da audiência de instrução e julgamento."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',54,'Legislação Institucional (PM-SP)',null,'De acordo com a Diretriz PM3-1/02/20, que estabelece Normas para o Sistema Operacional de Policiamento PM – NORSOP, é correto afirmar que','{"A": "o único objetivo expressamente mencionado na Diretriz PM3-1/02/20 é padronizar a sistemática de emprego operacional.", "B": "para alicerçar as práticas organizacionais, destacam-se os seguintes princípios básicos: Polícia Comunitária, Direitos Humanos e Excelência da gestão.", "C": "o Sistema Operacional de Policiamento PM baseia-se, exclusivamente, na Matriz Operacional do Policiamento Preventivo.", "D": "o Programa de Radiopatrulha está inserido nos Programas de Policiamento Complementares, enquanto o Programa de Policiamento Escolar está inserido nos Programas de Policiamento Primários."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',55,'Legislação Institucional (PM-SP)',null,'Em uma abordagem policial com viatura “4 rodas”, a equipe de policiais, composta por 2 (dois) integrantes, se deparou com pessoas em atitude sob fundada suspeita. Nesse caso, de acordo com o “Procedimento Operacional Padrão – processo 1.02.00 – Abordagem Policial com viatura 4 rodas”, é correto afirmar que','{"A": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado e as armas no coldre.", "B": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado e as armas na posição “3º Olho”.", "C": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado e as armas na posição “Sul”.", "D": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado, estando um deles com a arma na posição “3º Olho” e o outro com a arma no coldre."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',56,'Legislação Institucional (PM-SP)',null,'De acordo com a Ordem de Serviço PM3-11/02/18-CIRCULAR, que dispôs sobre o uso de dispositivos luminosos (faróis/giroflex) e/ou sonoros (sirenes/buzinas) pelas viaturas, é correto afirmar que','{"A": "o uso do dispositivo luminoso de emergência (giroflex) deverá ocorrer, durante o dia e a noite, em todos os deslocamentos e estacionamentos preventivos.", "B": "o uso de sirenes será obrigatório, durante o dia ou à noite, nos deslocamentos para atendimento de ocorrências, desde que caracterizada a condição de emergência.", "C": "todas as viaturas caracterizadas da Instituição, nos seus deslocamentos, deverão trafegar com os faróis baixos (luzes baixas) ligados após as 18h.", "D": "as viaturas, mesmo em situações de emergência, não poderão utilizar os faróis altos."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',57,'Legislação Institucional (PM-SP)',null,'De acordo com a Diretriz PM3-5/02/20 – Programa de Policiamento Comunitário, “a atuação direcionada a localidades específicas, estabelecidas conforme critérios estratégicos, visando alcançar níveis aceitáveis de segurança pública e qualidade de vida, por meio do respaldo, cooperação, parceria, participação e coleta de informações junto às respectivas comunidades” corresponde ao conceito de','{"A": "policiamento ostensivo comunitário.", "B": "polícia comunitária.", "C": "patrulha comunitária.", "D": "visita comunitária."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',58,'Legislação Institucional (PM-SP)',null,'Há situações que exigem o emprego de efetivo com treinamento tático diferenciado para atuação em ocorrências mais graves, como homicídios, sequestros e roubos. De acordo com a Diretriz PM3-3/02/20 – Programa de Força Tática, assinale a afirmativa incorreta.','{"A": "O Programa FT consiste em Programa de Policiamento Primário, sendo, juntamente com o Programa de Radiopatrulha, prioritário em relação aos demais Programas de Policiamento e Atividades Operacionais Diversas.", "B": "Entre as atividades típicas de apoio tático, menciona-se o controle sobre a criminalidade violenta, mediante a saturação coordenada de áreas de interesse da segurança pública (por exemplo, prevenção a roubos em estabelecimentos bancários, com perímetro de atuação predefinido).", "C": "O Programa de Força Tática tem por objetivo organizar o desenvolvimento do policiamento ostensivo e os apoios táticos executados pelas Forças Táticas.", "D": "O suporte operacional especializado para o atendimento às ocorrências e incidentes graves e/ou passíveis de repercussão, assim classificadas segundo as NORSOP, não é atividade típica de apoio tático."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',59,'Legislação Institucional (PM-SP)',null,'A execução de alguns serviços e atividades pode ser delegada, por meio de convênio firmado entre o Estado e os municípios, à Polícia Militar. De acordo com a Diretriz PM3-2/02/14 – Atividade Delegada, é correto afirmar que','{"A": "o efetivo policial-militar designado para a atividade delegada será prioritariamente empregado nas missões definidas como objeto do convênio celebrado com o respectivo município, não podendo ser designado previamente em outras atividades e/ou operações policial-militares ordinárias.", "B": "o policiamento escalado ordinariamente nas mesmas localidades em que atua o efetivo policial-militar designado para a atividade delegada deverá atuar, conjuntamente, nas missões definidas no convênio celebrado.", "C": "a execução da atividade delegada não poderá ser suspensa até o término do convênio.", "D": "o policial militar empregado em atividade delegada estará sujeito à carga horária limite de até 12 (doze) horas diárias e não poderá ultrapassar o teto de 120 (cento e vinte) horas mensais, dentro do mês considerado, independentemente da quantidade de convênios a que se voluntariou."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',60,'Direito Penal',null,'Maria, menor de 13 anos de idade, manteve, consensualmente, relação sexual com seu namorado, José, de 18 anos de idade. Nesse caso, de acordo com o Código Penal, é correto afirmar que','{"A": "o consentimento de Maria exclui a ilicitude da conduta de José e, portanto, não há de se falar em crime de estupro de vulnerável.", "B": "a conduta de José somente seria qualificada como crime de estupro de vulnerável caso Maria não tivesse mantido relações sexuais prévias com outra pessoa antes da relação sexual com José.", "C": "José cometeu estupro de vulnerável, independentemente do consentimento da vítima ou de Maria já ter tido relações sexuais prévias com outra pessoa.", "D": "o crime de estupro de vulnerável somente ocorre quando há violência ou grave ameaça contra a vítima."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno')
